// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz parameters: from (actor), uint256 v, and an array of single recipient addresses encoded as bytes
    // We keep _tos length = 1 by deriving it from a single fuzzed address `toAddr` so the loop runs exactly once
    function testFuzz_property(address from, address toAddr, uint256 v) public {
        // admissible domain: non-zero recipient address and non-empty _tos ensured by using toAddr and length 1
        vm.assume(toAddr != address(0));

        // Deploy a Recording token-like contract that exposes the exact selector
        // transferFrom(address,address,uint256) -> we declare it here so a correct selector will invoke this function
        Recorder recorder = new Recorder();

        // Prepare the single-element array for the call
        address[] memory tos = new address[](1);
        tos[0] = toAddr;

        // We will route the transfer to the recorder, but only when the recorder's address equals toAddr
        // If the fuzzer supplied a different toAddr, set tos[0] to recorder's address instead so we still exercise the recorder
        if (toAddr != address(recorder)) {
            tos[0] = address(recorder);
        }

        // Ensure 'from' has some balance in the test environment if needed by external logic (not used here), but keep it wide
        vm.deal(from, 1 ether);

        // Call c.transfer and observe whether it reverts or not
        bool ok;
        try c.transfer(from, address(recorder), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: Reference contract always succeeds (ok == true) for any non-empty tos array
        // The mutant that computes a wrong selector can cause the external call to fail (the recorder's function won't be called)
        // and thus transfer will revert for some inputs; therefore we assert that c.transfer does not revert here.
        assertTrue(ok);

        // Additionally, verify that when the call succeeded, the recorder observed exactly one call with the expected decoded args
        // This reads the recorder's public getters (observable external behavior) but does not write them.
        if (ok) {
            (uint256 calls, address observedFrom, address observedTo, uint256 observedV) = recorder.getLastCall();
            // calls should be at least 1 and the last recorded args must match the call we made
            assertTrue(calls >= 1);
            assertTrue(observedFrom == from);
            assertTrue(observedTo == tos[0]);
            assertTrue(observedV == v);
        }
    }
}

// Recorder exposes the exact target signature so a correct selector invokes this function and records the arguments.
contract Recorder {
    uint256 public calls;
    address public lastFrom;
    address public lastTo;
    uint256 public lastV;

    // matches selector: transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        calls += 1;
        lastFrom = from;
        lastTo = to;
        lastV = amount;
        return true;
    }

    // helper to read the recorded last call in one getter
    function getLastCall() external view returns (uint256, address, address, uint256) {
        return (calls, lastFrom, lastTo, lastV);
    }
}
